import {
  DEITY_COLOR_FIELDS, normalizeDeityColors, deityColorsEqual, effectiveDeityColors,
  clampDeityGeometry, deityGeometryEqual, deityPositionLimit, previewDeityArt,
} from '../app/deity-art.js';
import { readDeityCustomization, saveDeityCustomization, canCustomizeDeity } from '../app/deity-customization.js';
import { deitySymbolPresentation } from '../app/deity-symbol.js';
import { dgnBadgePath } from '../app/dgn-traits.js';
import { recolorDeitySymbolRing } from '../app/deity-symbol-art.js';
import { subscribe } from '../app/store.js';
import { compactUiError } from '../app/ui-error.js';
import { lock, unlock } from '../app/scroll-lock.js';

const SWATCHES = [
  ['Pink', '#ff00ff'], ['Purple', '#3f1a82'], ['Green', '#30d100'], ['Red', '#ed0e11'],
  ['Blue', '#0066ff'], ['Orange', '#ff8c00'], ['Silver', '#d9d9d9'], ['Gold', '#ab8d3f'],
];
const LABELS = ['Rim', 'Badge background', 'Symbol ink', 'Card background', 'Card outline'];
let stylesReady;
function loadStyles() {
  if (!stylesReady) stylesReady = new Promise((resolve, reject) => {
    const link = document.createElement('link');
    link.rel = 'stylesheet'; link.href = '/app/styles/deity-art-editor.css?v=holder-customizer-20260929';
    link.onload = resolve;
    link.onerror = () => { link.remove(); stylesReady = null; reject(new Error('Could not load the customizer. Try again.')); };
    document.head.append(link);
  });
  return stylesReady;
}

export async function openDeityCustomizer(symbolId, returnFocus = document.activeElement, { canOpen = () => true } = {}) {
  if (!canOpen()) return null;
  const championPath = dgnBadgePath(symbolId >> 3, symbolId & 7, symbolId === 0 ? 3 : symbolId === 6 ? 2 : 6);
  const [state, championSvg] = await Promise.all([
    readDeityCustomization(symbolId),
    fetch(championPath).then(response => {
      if (!response.ok) throw new Error('Could not load the symbol preview. Try again.');
      return response.text();
    }),
    loadStyles(),
  ]);
  if (!canOpen()) return null;
  if (!canCustomizeDeity(state.owner)) throw new Error('Connect the wallet that owns this Deity Pass to customize it.');
  return openDeityArtEditor({
    state, championSvg, returnFocus,
    canEdit: () => canCustomizeDeity(state.owner),
    onSave: change => saveDeityCustomization({ ...change, symbolId, owner: state.owner, renderer: state.renderer }),
  });
}

/** Colors and layout have separate on-chain transactions, so each tab saves itself. */
export function openDeityArtEditor({ state, championSvg, onSave, canEdit = () => false, returnFocus = document.activeElement }) {
  const { symbolId, defaults, bounds, appearance } = state;
  const symbol = deitySymbolPresentation(symbolId);
  let savedColors = { ...state.colors }, colors = { ...savedColors };
  let savedGeometry = { ...state.geometry }, geometry = { ...savedGeometry };
  let savedGeometryOverride = state.geometryOverride, geometryOverride = savedGeometryOverride;
  let tab = 'colors', busy = false, closed = false;
  const opener = returnFocus;
  const dialog = document.createElement('dialog');
  dialog.className = 'deity-art-editor';
  dialog.setAttribute('aria-labelledby', 'deity-art-title');
  dialog.innerHTML = `
    <header class="deity-art-editor__header">
      <div><span class="deity-art-editor__eyebrow">YOUR DEITY PASS</span><h2 id="deity-art-title">Make your mark</h2><p data-art="name"></p></div>
      <button type="button" data-art="close" class="deity-art-editor__close" aria-label="Close Deity customizer">×</button>
    </header>
    <div class="deity-art-editor__body">
      <section class="deity-art-editor__previews" aria-label="Live artwork preview">
        <div class="deity-art-editor__champion"><span>IN DEGENERETTE</span><div><img data-art="champion" alt="Degenerette champion preview"></div><strong data-art="champion-name"></strong></div>
        <div class="deity-art-editor__nft"><img data-art="nft" alt="Full Deity Pass NFT preview"><span>YOUR NFT<small>Live preview</small></span></div>
        <p class="deity-art-editor__scope">Your ring color appears in Degenerette.<br>The other controls style your NFT.</p>
      </section>
      <form class="deity-art-editor__controls">
        <div class="deity-art-editor__tabs" role="tablist" aria-label="Customization controls">
          <button type="button" role="tab" id="deity-colors-tab" aria-controls="deity-colors-panel" aria-selected="true" data-tab="colors">Colors <i data-dirty="colors" hidden aria-label="Unsaved changes">•</i></button>
          <button type="button" role="tab" id="deity-layout-tab" aria-controls="deity-layout-panel" aria-selected="false" tabindex="-1" data-tab="layout">Size & position <i data-dirty="layout" hidden aria-label="Unsaved changes">•</i></button>
        </div>
        <fieldset data-art="fields">
          <legend class="deity-art-editor__sr">Customize your pass</legend>
          <section id="deity-colors-panel" role="tabpanel" aria-labelledby="deity-colors-tab">
            ${DEITY_COLOR_FIELDS.map((key, i) => `
              <div class="deity-art-editor__color" data-color-row="${key}" ${key === 'symbolColor' && symbolId < 8 ? 'hidden' : ''}>
                <label for="deity-color-${key}"><b>${LABELS[i]}</b><small data-inherit="${key}">Default</small></label>
                <input id="deity-color-${key}" type="color" data-color="${key}" aria-label="${LABELS[i]}">
                <input type="text" data-hex="${key}" aria-label="${LABELS[i]} hex color" maxlength="7" spellcheck="false" autocomplete="off" pattern="#[0-9a-fA-F]{6}">
                <button type="button" data-default="${key}" aria-label="Use default ${LABELS[i].toLowerCase()}" title="Use default ${LABELS[i].toLowerCase()}">↺</button>
              </div>${i === 0 ? `<div class="deity-art-editor__swatches" aria-label="Rim color presets">${SWATCHES.map(([name, color]) => `<button type="button" data-swatch="${color}" style="--swatch:${color}" aria-label="${name} rim" title="${name}"></button>`).join('')}</div>` : ''}`).join('')}
            <p class="deity-art-editor__note">${symbolId < 8 ? 'Crypto logos keep their original ink. ' : ''}↺ returns a color to its inherited default.</p>
          </section>
          <section id="deity-layout-panel" role="tabpanel" aria-labelledby="deity-layout-tab" hidden>
            ${[['radius', 'Badge size'], ['centerX', 'Horizontal position'], ['centerY', 'Vertical position']].map(([key, label]) => `<label class="deity-art-editor__slider"><span>${label}<output data-output="${key}"></output></span><input type="range" data-geometry="${key}" aria-label="${label}" step="1"></label>`).join('')}
            <div class="deity-art-editor__layout-actions"><button type="button" data-art="center">CENTER BADGE</button><button type="button" data-art="default-layout">DEFAULT LAYOUT</button></div>
            <p class="deity-art-editor__note">The badge stays inside the card. Increasing its size brings it inward when needed.</p>
          </section>
        </fieldset>
        <div class="deity-art-editor__footer"><button type="button" data-art="undo">UNDO</button><button type="submit" data-art="save" disabled>SAVE COLORS</button></div>
        <p class="deity-art-editor__status" data-art="status" role="status" aria-live="polite"></p>
        <button type="button" class="deity-art-editor__restore" data-art="restore">Restore all defaults</button>
      </form>
    </div>`;
  const node = key => dialog.querySelector(`[data-art="${key}"]`);
  node('name').textContent = symbol.title;
  node('champion-name').textContent = symbol.name;
  const colorsDirty = () => !deityColorsEqual(colors, savedColors);
  const layoutDirty = () => geometryOverride !== savedGeometryOverride || !deityGeometryEqual(geometry, savedGeometry);
  const defaultGeometry = () => ({ radius: bounds.defaultRadius, centerX: 0, centerY: 0 });

  function render({ syncInputs = true } = {}) {
    if (closed) return;
    const effective = effectiveDeityColors(colors, defaults);
    let valid = true;
    try {
      const preview = previewDeityArt(appearance, effective, geometry, symbolId, bounds);
      node('champion').src = `data:image/svg+xml,${encodeURIComponent(recolorDeitySymbolRing(championSvg, effective.rimColor))}`;
      node('nft').src = preview.src;
    } catch (error) {
      valid = false; node('status').textContent = error.message;
    }
    for (const key of DEITY_COLOR_FIELDS) {
      if (key === 'symbolColor' && symbolId < 8) continue;
      const hex = dialog.querySelector(`[data-hex="${key}"]`);
      const color = dialog.querySelector(`[data-color="${key}"]`);
      const colorValid = /^#[0-9a-f]{6}$/i.test(effective[key]);
      if (colorValid) color.value = effective[key];
      if (syncInputs) hex.value = effective[key];
      hex.setAttribute('aria-invalid', String(!colorValid));
      dialog.querySelector(`[data-inherit="${key}"]`).textContent = colors[key] ? 'Custom' : 'Default';
      dialog.querySelector(`[data-default="${key}"]`).disabled = !colors[key];
    }
    const limit = deityPositionLimit(geometry.radius, bounds);
    for (const key of ['radius', 'centerX', 'centerY']) {
      const input = dialog.querySelector(`[data-geometry="${key}"]`);
      input.min = key === 'radius' ? bounds.minRadius : -limit;
      input.max = key === 'radius' ? bounds.maxRadius : limit;
      input.value = geometry[key];
      // Geometry uses 0.01 SVG units; the card is 100 units wide.
      dialog.querySelector(`[data-output="${key}"]`).textContent = key === 'radius'
        ? `${(geometry.radius / bounds.defaultRadius * 100).toFixed(1)}%`
        : geometry[key] === 0 ? 'Centered' : `${geometry[key] > 0 ? '+' : ''}${(geometry[key] / bounds.unitsPerSvgUnit).toFixed(2)}`;
    }
    for (const button of dialog.querySelectorAll('[data-swatch]')) button.setAttribute('aria-pressed', String(button.dataset.swatch === effective.rimColor?.toLowerCase()));
    const allowed = canEdit();
    node('fields').disabled = busy;
    for (const button of dialog.querySelectorAll('[data-tab]')) {
      const selected = button.dataset.tab === tab;
      button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; button.disabled = busy;
      dialog.querySelector(`#deity-${button.dataset.tab}-panel`).hidden = !selected;
    }
    dialog.querySelector('[data-dirty="colors"]').hidden = !colorsDirty();
    dialog.querySelector('[data-dirty="layout"]').hidden = !layoutDirty();
    node('undo').disabled = busy || !(tab === 'colors' ? colorsDirty() : layoutDirty());
    node('save').disabled = busy || !valid || !allowed || !(tab === 'colors' ? colorsDirty() : layoutDirty());
    node('save').textContent = busy ? 'SAVING…' : tab === 'colors' ? 'SAVE COLORS' : 'SAVE LAYOUT';
    node('restore').disabled = busy || !allowed || !(Object.values(savedColors).some(Boolean) || savedGeometryOverride);
    if (!allowed) node('status').textContent = 'Connect the wallet that owns this pass to save changes.';
  }
  for (const input of dialog.querySelectorAll('[data-color], [data-hex]')) input.addEventListener('input', () => {
    const key = input.dataset.color || input.dataset.hex;
    colors[key] = input.value.trim().toLowerCase();
    node('status').textContent = '';
    render({ syncInputs: Boolean(input.dataset.color) });
  });
  for (const button of dialog.querySelectorAll('[data-default]')) button.addEventListener('click', () => {
    colors[button.dataset.default] = ''; node('status').textContent = ''; render();
  });
  for (const button of dialog.querySelectorAll('[data-swatch]')) button.addEventListener('click', () => {
    colors.rimColor = button.dataset.swatch; node('status').textContent = ''; render();
  });
  for (const input of dialog.querySelectorAll('[data-geometry]')) input.addEventListener('input', () => {
    geometry = clampDeityGeometry({ ...geometry, [input.dataset.geometry]: Number(input.value) }, bounds);
    geometryOverride = true; node('status').textContent = ''; render();
  });
  const chooseTab = value => { tab = value; node('status').textContent = ''; render(); };
  for (const button of dialog.querySelectorAll('[data-tab]')) {
    button.addEventListener('click', () => chooseTab(button.dataset.tab));
    button.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault(); chooseTab(event.key === 'Home' ? 'colors' : event.key === 'End' ? 'layout' : tab === 'colors' ? 'layout' : 'colors');
      dialog.querySelector(`[data-tab="${tab}"]`).focus();
    });
  }
  node('center').addEventListener('click', () => { geometry = { ...geometry, centerX: 0, centerY: 0 }; geometryOverride = true; node('status').textContent = ''; render(); });
  node('default-layout').addEventListener('click', () => { geometry = defaultGeometry(); geometryOverride = false; node('status').textContent = ''; render(); });
  node('undo').addEventListener('click', () => {
    if (tab === 'colors') colors = { ...savedColors };
    else { geometry = { ...savedGeometry }; geometryOverride = savedGeometryOverride; }
    node('status').textContent = ''; render();
  });
  async function save(kind) {
    if (busy || !canEdit() || typeof onSave !== 'function') return;
    const nextColors = kind === 'colors' ? normalizeDeityColors(colors, symbolId) : null;
    const nextGeometry = kind === 'geometry' && geometryOverride ? { ...geometry } : null;
    busy = true;
    node('status').textContent = 'Confirm the artwork change in your wallet…'; render();
    try {
      await onSave({ kind, colors: nextColors, geometry: nextGeometry });
      if (kind === 'colors') { savedColors = { ...nextColors }; colors = { ...nextColors }; }
      if (kind === 'geometry') { savedGeometry = { ...geometry }; savedGeometryOverride = geometryOverride; }
      if (kind === 'all-defaults') {
        savedColors = normalizeDeityColors({}, symbolId); colors = { ...savedColors };
        savedGeometry = defaultGeometry(); geometry = { ...savedGeometry };
        savedGeometryOverride = geometryOverride = false;
      }
      node('status').textContent = kind === 'colors' ? 'Colors saved on chain.' : kind === 'geometry' ? 'Layout saved on chain.' : 'Default artwork restored on chain.';
    } catch (error) {
      node('status').textContent = compactUiError(error, 'Could not save. Your changes are here to retry.');
    } finally { busy = false; render(); }
  }
  dialog.querySelector('form').addEventListener('submit', event => {
    event.preventDefault(); if (!node('save').disabled) void save(tab === 'colors' ? 'colors' : 'geometry');
  });
  node('restore').addEventListener('click', () => { if (!node('restore').disabled) void save('all-defaults'); });
  node('close').addEventListener('click', () => dialog.close());
  // Native dialog contains keyboard focus; a click outside its rectangle dismisses it.
  dialog.addEventListener('click', event => {
    if (event.target !== dialog) return;
    const box = dialog.getBoundingClientRect();
    if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) dialog.close();
  });
  const unsubs = ['connected.address', 'viewing.address', 'ui.mode'].map(key => subscribe(key, () => render()));
  dialog.addEventListener('close', () => {
    closed = true; unsubs.forEach(fn => fn()); unlock(); dialog.remove(); opener?.focus?.({ preventScroll: true });
  }, { once: true });
  document.body.append(dialog); render(); dialog.showModal(); lock(); node('close').focus({ preventScroll: true });
  return dialog;
}
